# Build regex to handle: "N stars", "N star", "stars count of N", commas allowed
star_re1 = re.compile(r'([0-9][0-9,]*)\s+stars?\b', re.IGNORECASE)
star_re2 = re.compile(r'stars?\s+count\s+of\s+([0-9][0-9,]*)', re.IGNORECASE)

def parse_stars(text):
    if not isinstance(text, str):
        return None
    m = star_re1.search(text)
    if m:
        return int(m.group(1).replace(',', ''))
    m = star_re2.search(text)
    if m:
        return int(m.group(1).replace(',', ''))
    return None

pi['stars'] = pi['Project_Information'].apply(parse_stars)
print("rows missing stars:", pi['stars'].isna().sum())
print(pi[pi['stars'].isna()].head(10))

# Add another pattern: "starred by N users"
star_re3 = re.compile(r'starred\s+by\s+([0-9][0-9,]*)\s+users?', re.IGNORECASE)
def parse_stars(text):
    if not isinstance(text, str):
        return None
    m = star_re1.search(text)
    if m:
        return int(m.group(1).replace(',', ''))
    m = star_re2.search(text)
    if m:
        return int(m.group(1).replace(',', ''))
    m = star_re3.search(text)
    if m:
        return int(m.group(1).replace(',', ''))
    return None

pi['stars'] = pi['Project_Information'].apply(parse_stars)
print("rows missing stars:", pi['stars'].isna().sum())

# Extract slug from Project_Information
slug_patterns = [
    re.compile(r'The project ([\w\-\._]+/[\w\-\._]+)\b', re.IGNORECASE),
    re.compile(r'GitHub project (?:named\s+)?([\w\-\._]+/[\w\-\._]+)\b', re.IGNORECASE),
    re.compile(r'(?:repository|hosted on GitHub under the name|under the repository(?: name)?)\s+([\w\-\._]+/[\w\-\._]+)\b', re.IGNORECASE),
    re.compile(r'titled\s+([\w\-\._]+/[\w\-\._]+)\b', re.IGNORECASE),
    re.compile(r'\b([\w\-\._]+/[\w\-\._]+)\b'),  # fallback: first slug-like
]

def parse_slug(text):
    if not isinstance(text, str):
        return None
    for pat in slug_patterns:
        m = pat.search(text)
        if m:
            return m.group(1)
    return None

pi['slug'] = pi['Project_Information'].apply(parse_slug)
print("missing slug:", pi['slug'].isna().sum())
